"""Evidence-linked English report, regenerated from the actual analysis tables."""
from html import escape
import json
from .figures import FIGURE_NAMES


def table(headers,rows):
    return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+escape(str(v))+'</th>' for v in headers)+'</tr></thead><tbody>'+''.join(
        '<tr>'+''.join('<td>'+escape(str(v))+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'


def build_report(summary,audit,config,root):
    s=summary
    n=s['n_events']
    depth=s['depth_counts']
    known=n-depth['Missing']
    region=max(s['regions'],key=lambda r:r['count'])
    region_known=[r for r in s['regions'] if r['deep_pct_known_depth'] is not None]
    deepest=max(region_known,key=lambda r:r['deep_pct_known_depth'])
    captions=[
        'Annual counts share the same M≥5 threshold and full calendar-year exposure. Changes are descriptive catalogue differences.',
        'Every box uses the full study period. Raw regional counts are not normalized by area or tectonic-boundary length.',
        'Every retained event is plotted with an equal-size marker. Color encodes depth class; overlap hides some points.',
        'Distances are exact for the chosen spherical minor-arc model, with all recorded distances shown. Geological and map uncertainty are not quantified.',
        'Each ECDF has its own regional denominator. Unequal box geometry and tectonic composition affect comparisons.',
        'Missing depths are excluded from the histogram only; negative catalogue depths are retained rather than automatically removed.',
        'Median and IQR summarize each region. Whiskers follow the 1.5-IQR convention; displayed outliers remain in the data.',
        'These are longitude–depth projections across the full latitude extent of each regional box, not narrow trench-normal sections. Vertical scales are exaggerated.',
        'Magnitude bins have width 0.1. The extraction is truncated below M5; magnitude types are not homogenized.',
        'The curve counts recorded events with magnitude at least each threshold. No frequency forecast or completeness-adjusted b-value is fitted.',
        'Hexagons count all available pairs; color uses a logarithmic count scale. Pooled association can hide regional differences.',
        'Each anchor is excluded; the two exposure windows are [−30,0) and [0,30) days within 500 km. Only M≥5 events are included.'
    ]
    def figure(i):
        return f'<figure id="figure-{i}"><a href="figures/{FIGURE_NAMES[i-1]}.png"><img loading="lazy" src="figures/{FIGURE_NAMES[i-1]}.png" alt="Figure {i}: {escape(captions[i-1])}"></a><figcaption><strong>Figure {i}.</strong> {escape(captions[i-1])}</figcaption></figure>'
    numeric_rows=[]
    for key,label in [('mag','Magnitude'),('depth','Depth (km)'),('boundary_distance_km','Boundary distance (km)')]:
        r=s['numeric'][key]
        fmt=lambda x:'—' if x is None else f'{x:.2f}'
        numeric_rows.append([label,r['n'],fmt(r['mean']),fmt(r['median']),fmt(r['std']),fmt(r['iqr']),fmt(r['q05']),fmt(r['q95']),f"{r['missing_pct']:.2f}%"])
    region_table=table(['Geographic box','N','Median depth km','Deep % of known depths','Median boundary km','Within 100 km %'],[
        [r['region'],f"{r['count']:,}",f"{r['median_depth_km']:.1f}" if r['median_depth_km'] is not None else '—',
         f"{r['deep_pct_known_depth']:.1f}" if r['deep_pct_known_depth'] is not None else '—',
         f"{r['median_boundary_distance_km']:.1f}" if r['median_boundary_distance_km'] is not None else '—',
         f"{r['within_100km_pct']:.1f}" if r['within_100km_pct'] is not None else '—'] for r in s['regions']])
    case_table=table(['Case','Anchor magnitude','Anchor UTC','Before count','After count','Complete windows'],[
        [r['name'],r['anchor_magnitude'],r['anchor_time'],r['before_count'],r['after_count'],'Yes' if r['fully_observed'] else 'No'] for r in s['cases']])
    correlations=table(['Pair','Pairwise N','Spearman rho'],[[r['x']+' / '+r['y'],r['n'],'—' if r['rho'] is None else f"{r['rho']:.3f}"] for r in s['correlations_all']])
    audit_table=table(['Step','Removed','Remaining'],[[r['reason'],r['removed'],r['remaining']] for r in audit['steps']])
    boxes=table(['Priority','Region','Longitude interval','Latitude interval'],[
        [i+1,r['name'],f"[{r['lon'][0]}, {r['lon'][1]})"+(' across date line' if r['lon'][0]>r['lon'][1] else ''),str(r['lat'])] for i,r in enumerate(config['regions'])])
    content=f'''
<header><div class="eyebrow">DSC5002 · BASELINE RESULTS · 30 OCTOBER 2026</div><h1>Inside the Earth</h1><p>Global earthquake patterns in space time and depth</p><a href="dashboard.html">Open the offline interactive dashboard →</a></header>
<main><section class="lead"><h2>What the catalogue shows</h2><p>This baseline analyzes <strong>{n:,} recorded earthquakes</strong> with preferred magnitude M≥5 in 2000–2025 UTC. In the selected spherical map model, <strong>{s['within_boundary_km_pct']['100']:.2f}%</strong> fall within 100 km of a PB2002 boundary. <strong>{depth['Shallow']/known*100:.2f}%</strong> of events with known depth are shallower than 70 km. These are descriptive observations from a thresholded catalogue and a simplified boundary layer.</p>
<p>All five questions in the supplied project plan are implemented. The report links every substantive result to a table or figure; calculations can be rebuilt from cached source files. It does not predict earthquakes or identify causal effects.</p></section>
<nav><a href="#data">Data</a><a href="#rq1">RQ1 Space and time</a><a href="#rq2">RQ2 Boundaries</a><a href="#rq3">RQ3 Depth</a><a href="#rq4">RQ4 Magnitude</a><a href="#rq5">RQ5 Major events</a><a href="#limits">Limits</a><a href="#sources">Sources</a></nav>
<section id="data"><h2>Data and audit</h2><p>The fixed extraction covers [2000-01-01, 2026-01-01) UTC, M≥{config['min_magnitude']:g}, event type earthquake. The USGS count receipt and deduplicated annual CSV batches both contain {audit['source_unique_in_period']:,} events. The 26 annual requests use inclusive service endpoints; stable IDs and the local half-open period prevent boundary duplication. {audit['input_rows']-n:,} rows were excluded in total.</p>
<p>There are {audit['missing_depth']:,} missing depths, {audit['negative_depth_retained']:,} retained negative depths, and {audit['suspicious_depth_above_800_km']:,} depths above 800 km. Large magnitudes and deep events were not removed as outliers. Raw files, URLs, access timestamps and SHA256 hashes are recorded in <code>data/sources.lock.json</code>; row-level exclusions are in <code>data/processed/cleaning_audit.json</code>.</p>{audit_table}
<h3>Numeric summaries</h3>{table(['Variable','N','Mean','Median','SD','IQR','5th percentile','95th percentile','Missing'],numeric_rows)}
<p>Table: <a href="tables/numeric_summary.csv">numeric_summary.csv</a>. Standard deviation uses n−1; all quantiles use pandas linear interpolation.</p></section>
<section id="rq1"><h2>RQ1 Where and when do earthquakes occur</h2><p>The largest annual catalogue count is {s['annual_max']['count']:,} in {s['annual_max']['year']}; the smallest is {s['annual_min']['count']:,} in {s['annual_min']['year']}. Among the named boxes and catch-all region, {escape(region['region'])} contains {region['count']:,} events. These comparisons describe a fixed-threshold catalogue; they do not measure equivalent-area regional rates or prove a change in underlying hazard.</p>
{figure(1)}{figure(2)}{figure(3)}{region_table}<p>Tables: <a href="tables/annual_counts.csv">annual counts</a>, <a href="tables/region_year_counts.csv">region by year</a>, <a href="tables/regional_summary.csv">regional summary</a>.</p></section>
<section id="rq2"><h2>RQ2 How close are events to mapped boundaries</h2><p>The median nearest-boundary distance is {s['numeric']['boundary_distance_km']['median']:.2f} km (IQR {s['numeric']['boundary_distance_km']['iqr']:.2f} km). The percentages within 50, 100 and 250 km are {s['within_boundary_km_pct']['50']:.2f}%, {s['within_boundary_km_pct']['100']:.2f}% and {s['within_boundary_km_pct']['250']:.2f}%. The analysis computes the exact shortest angular distance to the minor great-circle arc between each adjacent PB2002 vertex, then multiplies by R=6371.0088 km.</p>
<p>Both endpoints and the on-arc perpendicular projection are checked. No longitude/latitude pair is treated as a Cartesian coordinate, so the date line is handled geometrically. This is an exact calculation under a spherical line-segment model, not an ellipsoidal estimate, a measurement of actual plate-boundary width, or a correction for the dated PB2002 geometry. The selected file contains 241 features.</p>{figure(4)}{figure(5)}</section>
<section id="rq3"><h2>RQ3 How does depth vary by region</h2><p>There are {depth['Shallow']:,} shallow (&lt;70 km), {depth['Intermediate']:,} intermediate (70–&lt;300 km), and {depth['Deep']:,} deep (≥300 km) recorded events, plus {depth['Missing']:,} missing depths. {escape(deepest['region'])} has the highest deep-event share among these boxes, at {deepest['deep_pct_known_depth']:.2f}% of events with known depth. Regional composition and box choices influence this comparison.</p>{figure(6)}{figure(7)}{figure(8)}
<p>Tables: <a href="tables/region_depth_counts.csv">depth counts</a>, <a href="tables/depth_threshold_sensitivity.csv">alternative depth thresholds</a>. The dashboard also provides a local 3D hypocentre view; its east/north coordinate approximation is for visualization only.</p></section>
<section id="rq4"><h2>RQ4 How are magnitude and recorded frequency related</h2><p>The median preferred magnitude is {s['numeric']['mag']['median']:.1f}. There are {s['magnitude_at_least_7']:,} events at M≥7 and {s['magnitude_at_least_8']:,} at M≥8. The cumulative curve is a direct count above each observed magnitude threshold over the fixed 26-year period. Magnitude types remain as supplied by USGS; mixing them and truncating below M5 limit physical interpretation.</p>{figure(9)}{figure(10)}
<h3>Exploratory relationships</h3>{correlations}<p>These coefficients describe available pairs. Dependence within earthquake sequences, catalogue heterogeneity and pooled regional composition make an ordinary independent-observation significance interpretation unsuitable. No p-values or causal claims are reported. The same pairs are recomputed by region and by two equal 13-year periods, 2000–2012 and 2013–2025.</p>{figure(11)}<p>Tables: <a href="tables/magnitude_frequency.csv">exact magnitude survival counts</a>, <a href="tables/spearman_correlations.csv">pairwise and subgroup Spearman coefficients</a>.</p></section>
<section id="rq5"><h2>RQ5 What appears around selected major earthquakes</h2><p>The selected anchors are the largest-magnitude catalogue entries on the predefined dates for Sumatra Andaman (2004), Maule (2010), and Tohoku (2011). Each comparison uses a 500 km spherical epicentral radius, 30 days of exposure per side, and the same M≥5 threshold. The anchor ID is removed. The before window is [−30,0) days and the after window [0,30) days relative to its exact UTC timestamp. All selected windows are fully observed.</p>{case_table}
<p>The selected cases contain more recorded events in the after windows than in the before windows. This describes these sequences only. It is neither a counterfactual causal estimate nor a general test across major earthquakes; smaller events are absent by design.</p>{figure(12)}<p>Tables: <a href="tables/case_summary.csv">case statistics and IDs</a>, <a href="tables/case_window_sensitivity.csv">7/30/90-day and 250/500/1000-km sensitivity grid</a>. Event-level memberships are saved separately for each anchor date.</p></section>
<section><h2>Geographic definitions and sensitivity</h2><p>Regions are deterministic comparison boxes assigned in the following priority order. Longitude intervals are half-open and latitude intervals closed. An event in overlapping boxes belongs to the first matching box. All remaining events are Other. These are geographic buckets, not inferred tectonic zones.</p>{boxes}
<p>The analysis also contracts and expands each box by 2 degrees while retaining priority, compares shallow cutoffs of 60/70 km and deep cutoffs of 300/350 km, and varies the case-study windows and radii. These are descriptive sensitivity tables, not evidence of invariance or formal robustness tests. See <a href="tables/region_box_sensitivity.csv">region-box sensitivity</a>, <a href="tables/depth_threshold_sensitivity.csv">depth sensitivity</a>, and <a href="tables/case_window_sensitivity.csv">case sensitivity</a>.</p></section>
<section id="limits"><h2>Limits and remaining work</h2><p>The catalogue may change after download. An M5 cutoff reduces but does not establish uniform completeness over space, time or magnitude type. Recorded event counts are dependent within sequences. Region sizes, latitude ranges and boundary lengths differ. PB2002 simplifies complex and diffuse boundaries; spherical calculations do not remove these map limitations. Cross-sections project a wide latitude span and exaggerate vertical scale. Globe and 3D scatter views cap the displayed points for browser performance and disclose the selected/displayed counts; summaries and static figures use all eligible rows.</p>
<p>This baseline has no completeness model, magnitude homogenization, declustering, formal multiple-comparison inference, causal identification, hazard forecasting, animation, presentation deck or team assignment. Animation remains optional in the proposal and was omitted because the fixed-window timelines already show the selected sequences. The pipeline and report are a starting implementation for the project rather than a final scientific validation of all tectonic interpretations.</p></section>
<section id="sources"><h2>Sources and reproduction</h2><ol><li><a href="https://earthquake.usgs.gov/fdsnws/event/1/">USGS Earthquake Catalog FDSN Event Web Service</a>. Preferred observation-level catalogue entries; query parameters and access times are saved with each raw file.</li><li>Bird, P. (2003). An updated digital model of plate boundaries. <em>Geochemistry Geophysics Geosystems</em>, 4(3), 1027. <a href="https://doi.org/10.1029/2001GC000252">doi:10.1029/2001GC000252</a>. GeoJSON conversion by <a href="https://github.com/fraxen/tectonicplates">Hugo Ahlenius / Nordpil</a>, ODC-By 1.0; see downloaded license and source commit.</li><li><a href="https://www.naturalearthdata.com/downloads/110m-physical-vectors/">Natural Earth 1:110m physical vectors</a>, coastline and land polygons, public domain. Source commit is pinned in the manifest.</li></ol><p>Run <code>python run_pipeline.py</code> to download and build. Run <code>python run_pipeline.py --offline</code> to rebuild from the hash-verified cache, <code>python verify_results.py</code> for independent checks, and <code>python -m pytest -q</code> for unit tests. The offline dashboard embeds Plotly JavaScript, events and map geometry. The report references sibling PNG files; keep the outputs directory together.</p></section>
</main><footer>Inside the Earth · DSC5002 baseline · Generated from the saved data tables</footer>'''
    css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font:16px/1.65 "Segoe UI",sans-serif;color:#213548;background:#fff}header{padding:42px max(5vw,24px);background:#102b42;color:white}header h1{font-size:48px;letter-spacing:-1.5px;margin:10px 0 0}header p{font-size:22px;color:#c8dce9;margin:5px 0 20px}header a{color:#d1e8fa}.eyebrow{font-size:12px;letter-spacing:1.5px;color:#9dc4e4}main{max-width:1120px;padding:30px 28px;margin:auto}h2{font-size:27px;margin:38px 0 14px;line-height:1.25}h3{font-size:20px;margin:28px 0 10px}p{margin:12px 0 18px}nav{display:flex;flex-wrap:wrap;gap:10px 22px;padding:20px 0;border-bottom:1px solid #dbe3ea}.lead{font-size:18px}.lead h2{margin-top:8px}a{color:#2166ac}figure{margin:30px 0 40px}figure img{display:block;width:100%;height:auto;border:1px solid #e2e7ec}figcaption{font-size:13px;color:#526779;padding-top:10px}.table-wrap{overflow-x:auto;margin:20px 0}table{border-collapse:collapse;font-size:13px;width:100%;font-variant-numeric:tabular-nums}th,td{text-align:left;padding:10px 11px;border-bottom:1px solid #dbe3ea;vertical-align:top}th{background:#eef3f7}code{font-size:13px;background:#eef3f7;padding:2px 5px;overflow-wrap:anywhere}footer{font-size:12px;color:#63798b;padding:30px;text-align:center;border-top:1px solid #e2e7ec}@media(max-width:600px){main{padding:22px 16px}header{padding:28px 20px}header h1{font-size:38px}header p{font-size:19px}h2{font-size:23px}.lead{font-size:16px}}@media print{header{background:white;color:#213548;padding:15px 0}header p,header a,.eyebrow{color:#213548}main{padding:0}nav{display:none}figure{break-inside:avoid}a{color:#213548;text-decoration:none}h2,h3{break-after:avoid}footer{display:none}}'''
    html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Inside the Earth results report</title><style>'+css+'</style></head><body>'+content+'</body></html>'
    path=root/'outputs/report.html'
    path.write_text(html,encoding='utf-8')
    return path
